module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg load;
    reg [1:0] ena;
    reg [99:0] data;
    wire [99:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .load(load),
        .ena(ena),
        .data(data),
        .q(q)
    );

    // Clock generation
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    integer errors = 0;
    reg [99:0] expected_q;

    // Task to apply reset/load
    task do_load(input [99:0] val);
        begin
            @(posedge clk);
            load = 1;
            ena = 2'b00;
            data = val;
            expected_q = val;
            @(posedge clk);
            load = 0;
        end
    endtask

    // Task to rotate right
    task do_rot_right();
        begin
            @(posedge clk);
            load = 0;
            ena = 2'b01;
            // Right rotation: bit 0 moves to bit 99, others shift right
            expected_q = {expected_q[0], expected_q[99:1]};
        end
    endtask

    // Task to rotate left
    task do_rot_left();
        begin
            @(posedge clk);
            load = 0;
            ena = 2'b10;
            // Left rotation: bit 99 moves to bit 0, others shift left
            expected_q = {expected_q[98:0], expected_q[99]};
        end
    endtask

    // Task to hold / no rotate (test both 2'b00 and 2'b11)
    task do_hold(input [1:0] hold_ena);
        begin
            @(posedge clk);
            load = 0;
            ena = hold_ena;
            // expected_q remains unchanged
        end
    endtask

    initial begin
        // Initialize signals
        load = 0;
        ena = 2'b00;
        data = 100'b0;
        expected_q = 100'b0;

        // Wait for stability
        #12;

        // Test 1: Load pattern with alternating bits and a marker
        do_load(100'h3F0F_0F0F_0F0F_0F0F_0F0F_0F0F);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Test 2: Rotate Right multiple times
        repeat (5) begin
            do_rot_right();
            #1;
            if (q !== expected_q) errors = errors + 1;
        end

        // Test 3: Rotate Left multiple times
        repeat (5) begin
            do_rot_left();
            #1;
            if (q !== expected_q) errors = errors + 1;
        end

        // Test 4: Hold state with ena = 2'b00
        do_hold(2'b00);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Test 5: Hold state with ena = 2'b11
        do_hold(2'b11);
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Test 6: Load new data and do mixed operations
        do_load(100'h1234_5678_9ABC_DEF0_1234_5678_9A);
        #1;
        if (q !== expected_q) errors = errors + 1;

        do_rot_left();
        #1;
        if (q !== expected_q) errors = errors + 1;

        do_rot_right();
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Test 7: Load priority over enable
        @(posedge clk);
        load = 1;
        ena = 2'b10; // Left rotate requested, but load is active
        data = 100'hFEDC_BA98_7654_3210_FEDC_BA98_76;
        expected_q = 100'hFEDC_BA98_7654_3210_FEDC_BA98_76;
        @(posedge clk);
        load = 0;
        #1;
        if (q !== expected_q) errors = errors + 1;

        // Final Result Check
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
